mapper.select:
SELECT d.dev_nm AS "developerName",c.code_nm AS "jobName",
  (SELECT o.opp_nm FROM tb_sl_opp o WHERE o.opp_id=#{previousOpportunityId,jdbcType=VARCHAR}) AS "previousOpportunityName"
FROM tb_hr_dev d JOIN tb_sy_code c ON c.code_grp_id='JOB' AND c.code=#{jobCode}
WHERE d.dev_id=#{developerId}

SELECT EXISTS(SELECT 1 FROM tb_sl_rcmd_log r WHERE r.rcmd_type_cd='AI' AND r.user_act_cd='EXCL' AND r.job_cd=#{jobCode} AND r.dev_id=#{developerId}
  AND r.opp_id=#{opportunityId}AND r.proj_id=#{projectId}
  AND NOT EXISTS(SELECT 1 FROM tb_sy_chg_hist h WHERE h.trgt_tbl_nm='TB_SL_OPP' AND h.trgt_key=#{opportunityId}'TB_PJ_PROJ' AND h.trgt_key=#{projectId}
    AND (h.chg_type_cd='RESUME' OR (h.chg_item_nm IN ('OPP_STAT_CD','PROJ_STAT_CD') AND h.bfr_val='STOP' AND h.aft_val='ING')) AND h.reg_dttm>r.act_dttm))
